// Golden parity with ref/pixiv-dl (ENG-003): the vectors are generated by scripts/gen-golden.py,
// which runs the script's own plain_text and write_metadata.

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { buildMetadata, plainText, serializeJson } from '../../src/shared/metadata';

interface TextVector {
  in: string;
  out: string;
}
interface MetadataCase {
  name: string;
  artworkId: string;
  body: Record<string, unknown>;
  fileText: string;
}

const GOLDEN = new URL('../golden/', import.meta.url);
const plainTextVectors = JSON.parse(
  readFileSync(new URL('plain_text.json', GOLDEN), 'utf8'),
) as TextVector[];
const metadataCases = JSON.parse(
  readFileSync(new URL('write_metadata.json', GOLDEN), 'utf8'),
) as MetadataCase[];

const SCRIPT_URL_PREFIX = '"url": "https://www.pixiv.net/artworks/';

const hasNoDescription = (c: MetadataCase) => c.body.description == null;
const hasNoId = (c: MetadataCase) => !c.body.illustId && !c.body.id;

function replaceOnce(text: string, from: string, to: string): string {
  const parts = text.split(from);
  if (parts.length !== 2) throw new Error(`expected exactly one ${from} in the script's output`);
  return parts.join(to);
}

/** The script's bytes with the two deviations PRD §4.3 documents applied. */
function expectedFileText(c: MetadataCase): string {
  let text = c.fileText;
  // PRD: a missing field is null. The script ran plain_text(None) and wrote "".
  if (hasNoDescription(c)) text = replaceOnce(text, '"description": ""', '"description": null');
  // The script formatted None into the url; the extension uses the requested artwork id.
  if (hasNoId(c)) {
    text = replaceOnce(text, `${SCRIPT_URL_PREFIX}None"`, `${SCRIPT_URL_PREFIX}${c.artworkId}"`);
  }
  return text;
}

describe('golden: plain_text (ref/pixiv-dl)', () => {
  it('golden: plain_text.json has at least 50 vectors', () => {
    expect(plainTextVectors.length).toBeGreaterThanOrEqual(50);
  });

  it.each(plainTextVectors.map((v, i) => [i, v] as const))(
    'plainText: vector %i equals plain_text',
    (_index, v) => {
      expect(plainText(v.in)).toBe(v.out);
    },
  );
});

describe('golden: write_metadata (ref/pixiv-dl)', () => {
  it('golden: write_metadata.json has at least 10 cases', () => {
    expect(metadataCases.length).toBeGreaterThanOrEqual(10);
  });

  it('golden: includes a body with no description', () => {
    expect(metadataCases.some(hasNoDescription)).toBe(true);
  });

  it('golden: includes a body with no illustId and no id', () => {
    expect(metadataCases.some(hasNoId)).toBe(true);
  });

  it.each(metadataCases.map((c) => [c.name, c] as const))(
    'serializeJson(buildMetadata): %s equals the metadata.json write_metadata wrote',
    (_name, c) => {
      expect(serializeJson(buildMetadata(c.body, c.artworkId))).toBe(expectedFileText(c));
    },
  );
});
